{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace Table MapleMonk.BananaClub_db_Myntra_Master as With Unicommerce as ( WITH sale_orders AS ( SELECT Sale_Order_Code, Tracking_Number, Channel_Name, Seller_SKU_Code, Invoice_Code, Invoice_Created, Selling_Price, CGST, IGST, SGST, UTGST, Sale_Order_Status, Sale_Order_Item_Status, Shipping_Package_Status_Code, Delivery_Time FROM `MAPLEMONK.Bananaclub_DB_get_sale_orders` QUALIFY ROW_NUMBER() OVER (PARTITION BY Sale_Order_Code, Seller_SKU_Code ORDER BY 1) = 1 ), tally_returns AS ( SELECT Invoice_number, Sale_Order_Number, Product_SKU_Code, Date, CGST, IGST, SGST, UTGST, Total FROM `MAPLEMONK.Bananaclub_DB_get_tally_return_gst_report` QUALIFY ROW_NUMBER() OVER (PARTITION BY Sale_Order_Number, Product_SKU_Code ORDER BY 1) = 1 ) SELECT so.Sale_Order_Code as UN_Sale_Order_Code, Tracking_Number, so.Seller_SKU_Code as UN_Seller_SKU_Code, so.Invoice_Code as UN_Invoice_Code, so.Invoice_Created as UN_Invoice_Created , so.Selling_Price as UN_Selling_Price, so.CGST AS UN_CGST, so.IGST AS UN_IGST, so.SGST AS UN_SGST, so.UTGST AS UN_UTGST, so.Sale_Order_Status as UN_Sale_Order_Status, so.Sale_Order_Item_Status as UN_Sale_Order_Item_Status, so.Shipping_Package_Status_Code as UN_Shipping_Package_Status_Code, so.Delivery_Time as UN_Delivery_Time, tr.Invoice_number as UNTGST_Invoice_number, tr.Sale_Order_Number as UNTGST_Sale_Order_Number, tr.Product_SKU_Code as UNTGST_Product_SKU_Code, tr.Date as UNTGST_return_Date, tr.CGST AS UNTGST_CGST, tr.IGST AS UNTGST_IGST, tr.SGST AS UNTGST_SGST, tr.UTGST AS UNTGST_UTGST, tr.Total as UNTGST_Total FROM sale_orders so LEFT JOIN tally_returns tr ON LOWER(TRIM(so.Sale_Order_Code)) = LOWER(TRIM(tr.Sale_Order_Number)) AND LOWER(TRIM(so.Seller_SKU_Code)) = LOWER(TRIM(tr.Product_SKU_Code)) ) , Orders AS ( select order_release_id ,seller_order_id sellerOrderId ,coalesce(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%E3S\', created_on), SAFE.PARSE_DATE(\'%d-%m-%Y\', created_on)) created_on ,seller_sku_code SKU ,packet_id ,order_tracking_number trackingNumber ,cancellation_reason_id_fk ,cancellation_reason ,coalesce(SAFE.PARSE_DATETIME(\'%Y-%m-%d %H:%M:%E3S\', packed_on), SAFE.PARSE_DATE(\'%d-%m-%Y\', packed_on)) packed_on ,coalesce(SAFE.PARSE_DATETIME(\'%Y-%m-%d %H:%M:%E3S\', inscanned_on), SAFE.PARSE_DATE(\'%d-%m-%Y\', inscanned_on)) inscanned_on ,coalesce(SAFE.PARSE_DATETIME(\'%Y-%m-%d %H:%M:%E3S\', shipped_on), SAFE.PARSE_DATE(\'%d-%m-%Y\', shipped_on)) shipped_on ,coalesce(SAFE.PARSE_DATETIME(\'%Y-%m-%d %H:%M:%E3S\', delivered_on), SAFE.PARSE_DATE(\'%d-%m-%Y\', delivered_on)) delivered_on ,coalesce(SAFE.PARSE_DATETIME(\'%Y-%m-%d %H:%M:%E3S\', cancelled_on), SAFE.PARSE_DATE(\'%d-%m-%Y\', cancelled_on)) cancelled_on ,coalesce(SAFE.PARSE_DATETIME(\'%Y-%m-%d %H:%M:%E3S\', lost_date), SAFE.PARSE_DATE(\'%d-%m-%Y\', lost_date)) lost_date ,coalesce(safe.PARSE_DATETIME(\'%Y-%m-%d %H:%M\', return_creation_date), SAFE.PARSE_DATE(\'%d-%m-%Y\', return_creation_date)) return_creation_date ,final_amount ,1 as Quantity ,order_status ,city ,state ,zipcode ,order_line_id order_line_id from `MAPLEMONK.Bananaclub_DB_Myntra_Orders` qualify row_number() over(partition by seller_order_id,order_line_id order by 1) = 1 ), orderFlow AS ( SELECT tracking_no, date(DATE(PARSE_TIMESTAMP(\'%Y-%m-%dT%H:%M:%E*S%Ez\', order_date))) date, return_type, order_item_status FROM `MAPLEMONK.Bananaclub_DB_Myntra_OrderFlow` QUALIFY ROW_NUMBER() OVER(PARTITION BY tracking_no ORDER BY 1) = 1 ), Return AS ( SELECT type, status AS return_status, cast(quantity as int64) AS return_quantity, return_id, exchange_id, is_refunded, coalesce(SAFE.PARSE_DATE(\'%d-%m-%Y\', refunded_date) , SAFE.PARSE_DATE(\'%Y-%m-%d\', refunded_date)) AS refunded_date, coalesce(SAFE.PARSE_DATE(\'%d-%m-%Y\', order_rto_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', order_rto_date)) AS order_rto_date, seller_order_id, seller_sku_code, SAFE.PARSE_DATE(\'%d-%m-%Y\', return_created_date) AS return_created_date, return_tracking_number, order_line_id FROM `MAPLEMONK.Bananaclub_DB_Myntra_Returns` QUALIFY ROW_NUMBER() OVER(PARTITION BY seller_order_id,order_line_id ORDER BY 1) = 1 ), Collections AS ( SELECT seller_order_id, order_line_id, Payment_Date, Settled_Amount, Commission, IGST_TCS, CGST_TCS, SGST_TCS, tds, Logistics_Commission, pick_and_pack_fee, fixed_fee, Payment_Gateway_Fee FROM `MAPLEMONK.Bananaclub_DB_Myntra_Collections_new` QUALIFY ROW_NUMBER() OVER(PARTITION BY seller_order_id, order_line_id ORDER BY 1) = 1 ) SELECT o.*, CASE WHEN o.created_on < DATE \'2025-09-21\' AND o.final_amount <= 1049 THEN (o.final_amount / 105) * 100 WHEN o.created_on < DATE \'2025-09-21\' AND o.final_amount > 1049 THEN (o.final_amount / 112) * 100 WHEN o.created_on >= DATE \'2025-09-21\' AND o.final_amount <= 2799 THEN (o.final_amount / 105) * 100 WHEN o.created_on >= DATE \'2025-09-21\' AND o.final_amount > 2799 THEN (o.final_amount / 112) * 100 END AS Taxable, fo.return_type, fo.order_item_status, r.type as return_Table_Type, r.return_status, r.return_quantity, r.return_id, r.exchange_id, r.is_refunded, r.refunded_date, r.order_rto_date, r.return_created_date, r.return_tracking_number, c.Payment_Date, c.Settled_Amount, c.Commission, c.IGST_TCS, c.CGST_TCS, c.SGST_TCS, c.tds, c.Logistics_Commission, c.pick_and_pack_fee, c.fixed_fee, c.Payment_Gateway_Fee, UN.*, sm.name Product_Name, sm.style_no, REGEXP_REPLACE(sm.style_no, r\'/.*$\', \'\') style_group, sm.category, case when sm.category like \'%SHIRT%\' or sm.category like \'%JACKET%\' then \'Top\' when sm.category like \'%SHORTS%\' or sm.category like \'%TROUSER%\' then \'Bottom\' else \'Others\' end product_type, sm.sub_category, sm.size FROM Orders o LEFT JOIN orderFlow fo ON LOWER(TRIM(o.trackingNumber)) = LOWER(TRIM(fo.tracking_no)) LEFT JOIN Return r ON trim(lower(r.seller_order_id)) = lower(trim(o.sellerOrderId)) AND LOWER(TRIM(r.order_line_id)) = LOWER(TRIM(o.order_line_id)) LEFT JOIN Collections c ON LOWER(TRIM(c.seller_order_id)) = LOWER(TRIM(o.sellerOrderId)) AND LOWER(TRIM(c.order_line_id)) = LOWER(TRIM(o.order_line_id)) LEFT JOIN Unicommerce UN ON trim(lower(UN.UN_Sale_Order_Code)) = lower(trim(o.sellerOrderId)) AND LOWER(TRIM(UN.UN_Seller_SKU_Code)) = LOWER(TRIM(o.sku)) LEFT JOIN ( select distinct SPLIT(product_code, \'_\')[OFFSET(0)] sku , name , image_url image_link , color style_no , upper(category_name) category , upper(description) sub_category , upper(size) size , mrp , base_price selling_price from maplemonk.banana_club_unicommerce_get_product_master qualify row_number() over(partition by lower(trim(SPLIT(product_code, \'_\')[OFFSET(0)])) order by 1 ) = 1 )sm on LOWER(TRIM(o.sku)) = LOWER(TRIM(sm.sku)) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            